  vMes.forEach(r => { const k = r.conclusion || 'Sin conclusión'; conteo[k] = (conteo[k]||0)+1; });
  const colMap = { 'Seguimiento':'#3b82c4', 'Reserva':'#2d5a27', 'Descartado':'#c0392b', 'Re-agendado':'#c07a2a', 'Sin conclusión':'#9ca3af' };
