  const filasCatV = porCat.map(x=>({ oc:`abrirDetalleVentasDir('categoria','${escJs(x.k)}')`, c:[esc(x.k), x.n, _fmtMonto(x.monto), Math.round(x.monto/(totVendido||1)*100)+'%'] }));
