  filasDesc.push({ tot:true, c:['Total', ventas.length, _dirUsd(totLista), _dirUsd(totDesc), pD(totDesc,totLista), totM2?'$'+Math.round(totVendido/totM2).toLocaleString('es-BO'):'—'] });
