  let proy = null; if (dec.f.per === 'mes' && Rg.h < Rg.d + 32 * 864e5 && Rg.h === Math.min(ahora, Rg.h)) { const dias = Rg.meses[0]?.dias || 30, trans = Math.max(1, (Rg.h - Rg.d) / 864e5); if (trans < dias) proy = cob / trans * dias; }
